// One source for the Authfly layer shared by the 9 runtimes: packages/shared/src.
//   bun tools/gen-shared.ts           write every generated file
//   bun tools/gen-shared.ts --check   fail (exit 1) when a generated file is missing or differs (CI)
// JS runtimes (react, vue, svelte, solid, webcomponent) get byte copies of skin/*.ts, blocks/*.types.ts,
// components/lucide-icons.ts and styles/theme.css. templ / Twig / Latte / Jinja2 get the skin tables and the Lucide
// glyphs generated from skin/recipes.ts and components/lucide-icons.ts (their skin wrappers read those tables).
import { existsSync, readFileSync, readdirSync, writeFileSync } from "fs";
import { join } from "path";
import { RECIPES, TEXT, GAP, ALIGN, JUSTIFY, type Recipe } from "../packages/shared/src/skin/recipes";
import { LUCIDE } from "../packages/shared/src/components/lucide-icons";

const root = join(import.meta.dir, "..");
const S = join(root, "packages/shared/src");
const U = join(root, "packages/ui");
const check = process.argv.includes("--check");
const JS = ["react", "vue", "svelte", "solid", "webcomponent"];
const out = new Map<string, string>();

// JS runtimes: identical copies.
const shared = ["skin/recipes.ts", "skin/skin.ts", "components/lucide-icons.ts", "styles/theme.css",
  ...readdirSync(join(S, "blocks")).filter((f) => f.endsWith(".types.ts")).sort().map((f) => `blocks/${f}`)];
for (const rt of JS) for (const f of shared) out.set(`${rt}/src/${f}`, readFileSync(join(S, f), "utf8"));

// Server runtimes.
const HEAD = "Code generated by tools/gen-shared.ts from packages/shared/src. DO NOT EDIT.";
const q = (s: string) => JSON.stringify(s);
const php = (s: string) => `'${s.replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;
const svg = (n: Array<[string, Record<string, string>]>) =>
  n.map(([t, a]) => `<${t}${Object.entries(a).map(([k, v]) => ` ${k}="${v}"`).join("")}></${t}>`).join("");
const R = RECIPES as Record<string, Recipe>;
const names = Object.keys(R);
const icons = Object.keys(LUCIDE);
const cap = (s: string) => s[0].toUpperCase() + s.slice(1);

// Go (package authfly)
{
  const pad = (s: string, w: number) => s + " ".repeat(Math.max(0, w - s.length));
  const map = (o: Record<string, string>, ind: string) => {
    const w = Math.max(...Object.keys(o).map((k) => q(k).length + 1));
    return Object.entries(o).map(([k, v]) => `${ind}${pad(q(k) + ":", w)} ${q(v)},`).join("\n");
  };
  const nw = Math.max(...names.map((n) => q(n).length + 1));
  const rec = names.map((n) => {
    const r = R[n]; const parts = [`base: []string{${r.base.map(q).join(", ")}}`];
    if (r.variants) parts.push(`variants: map[string]string{${Object.entries(r.variants).map(([k, v]) => `${q(k)}: ${q(v)}`).join(", ")}}`);
    if (r.fallback) parts.push(`fallback: ${q(r.fallback)}`);
    return `\t${pad(q(n) + ":", nw)} {${parts.join(", ")}},`;
  }).join("\n");
  const tw = Math.max(...Object.keys(TEXT).map((k) => `Text${cap(k)}`.length));
  out.set("templ/authfly/skin_recipes_gen.go", `// ${HEAD}

package authfly

// skinRecipe: class groups in order, one group per variant, the variant used for an unknown one.
type skinRecipe struct {
	base     []string
	variants map[string]string
	fallback string
}

var skinRecipes = map[string]skinRecipe{
${rec}
}

const (
${Object.entries(TEXT).map(([k, v]) => `\t${pad(`Text${cap(k)}`, tw)} = ${q(v)}`).join("\n")}
)

var gapCls = map[string]string{${Object.entries(GAP).map(([k, v]) => `${q(k)}: ${q(v)}`).join(", ")}}
var alignCls = map[string]string{${Object.entries(ALIGN).map(([k, v]) => `${q(k)}: ${q(v)}`).join(", ")}}
var justifyCls = map[string]string{${Object.entries(JUSTIFY).map(([k, v]) => `${q(k)}: ${q(v)}`).join(", ")}}
`);
  const iw = Math.max(...icons.map((k) => q(k).length + 1));
  out.set("templ/authfly/lucide_icons.go", `// Generated by tools/gen-shared.ts from packages/shared/src/components/lucide-icons.ts (lucide 1.61.0, ISC). Do not edit by hand.
package authfly

// lucideSVG holds the inner SVG markup of each glyph (static, trusted data).
var lucideSVG = map[string]string{
${icons.map((n) => `\t${pad(q(n) + ":", iw)} ${q(svg(LUCIDE[n]))},`).join("\n")}
}
`);
}

// PHP (Twig, Latte): class SkinRecipes in each package namespace + the glyph table.
for (const rt of ["twig", "latte"]) {
  const arr = (o: Record<string, string>) => `[${Object.entries(o).map(([k, v]) => `${php(k)} => ${php(v)}`).join(", ")}]`;
  const rec = names.map((n) => {
    const r = R[n];
    return `        ${php(n)} => ['base' => [${r.base.map(php).join(", ")}], 'variants' => ${r.variants ? arr(r.variants) : "[]"}, 'fallback' => ${r.fallback ? php(r.fallback) : "null"}],`;
  }).join("\n");
  out.set(`${rt}/src/SkinRecipes.php`, `<?php
// ${HEAD}
declare(strict_types=1);

namespace Authfly\\${cap(rt)};

final class SkinRecipes
{
    /** name => base class groups, variants, fallback variant for an unknown one. */
    public const RECIPES = [
${rec}
    ];
    public const TEXT = ${arr(TEXT)};
    public const GAP = ${arr(GAP)};
    public const ALIGN = ${arr(ALIGN)};
    public const JUSTIFY = ${arr(JUSTIFY)};
}
`);
  out.set(`${rt}/src/lucide-icons.php`, `<?php
// Generated by tools/gen-shared.ts from packages/shared/src/components/lucide-icons.ts (lucide 1.61.0, ISC). Do not edit by hand.
declare(strict_types=1);

return [
${icons.map((n) => `    ${q(n)} => ${php(svg(LUCIDE[n]))},`).join("\n")}
];
`);
}

// Python (Jinja2)
{
  const d = (o: Record<string, string>) => `{${Object.entries(o).map(([k, v]) => `${q(k)}: ${q(v)}`).join(", ")}}`;
  const rec = names.map((n) => {
    const r = R[n];
    return `    ${q(n)}: {"base": [${r.base.map(q).join(", ")}], "variants": ${r.variants ? d(r.variants) : "{}"}, "fallback": ${r.fallback ? q(r.fallback) : "None"}},`;
  }).join("\n");
  out.set("jinja2/authfly_jinja/skin_recipes.py", `# ${HEAD}
"""Authfly skin tables: name -> base class groups, variants, fallback variant for an unknown one."""

RECIPES = {
${rec}
}
TEXT = ${d(TEXT)}
GAP = ${d(GAP)}
ALIGN = ${d(ALIGN)}
JUSTIFY = ${d(JUSTIFY)}
`);
  out.set("jinja2/authfly_jinja/lucide_icons.py", `# Generated by tools/gen-shared.ts from packages/shared/src/components/lucide-icons.ts (lucide 1.61.0, ISC). Do not edit by hand.
LUCIDE = {
${icons.map((n) => `    ${q(n)}: ${q(svg(LUCIDE[n]))},`).join("\n")}
}
`);
}

let bad = 0;
for (const [rel, body] of out) {
  const p = join(U, rel);
  const cur = existsSync(p) ? readFileSync(p, "utf8") : null;
  if (cur === body) continue;
  if (check) { console.error(`gen-shared: packages/ui/${rel} ${cur === null ? "missing" : "differs from packages/shared/src"}`); bad++; }
  else { writeFileSync(p, body); console.log(`gen-shared: wrote packages/ui/${rel}`); }
}
if (check) {
  if (bad) { console.error(`gen-shared: ${bad} file(s) out of date; run bun tools/gen-shared.ts`); process.exit(1); }
  console.log(`gen-shared: ${out.size} generated files up to date (${JS.length} JS runtimes x ${shared.length} + server skin/icons)`);
}
